import json, sys
data = json.load(sys.stdin)

# Pod D agents
pod_d = ['atrium','stitch','loom','conduit','lattice','mantle','lumen','onyx']
print('=== Pod D agents in /api/org-chart ===')
for aid in pod_d:
    n = next((x for x in data['nodes'] if x['id']==aid), None)
    if n:
        print(f'{aid:10} dept={str(n.get(\"department\")):15} subDept={str(n.get(\"subDepartment\")):25} pod={str(n.get(\"pod\")):25} cardEmoji={n.get(\"subDepartmentCardEmoji\")} color={n.get(\"subDepartmentColor\")}')

print()
print('=== Engineering subDepartments (cards) ===')
for d in data['departments']:
    if d['id'] != 'engineering':
        continue
    for sd in d.get('subDepartments', []):
        print(f'  {sd[\"id\"]:30} {sd.get(\"cardEmoji\",\"\")} {sd.get(\"cardLabel\") or sd.get(\"label\")} color={sd.get(\"color\")} status={sd.get(\"status\")} members={len(sd.get(\"members\",[]))}')
        for m in sd.get('members', []):
            print(f'      → {m[\"id\"]}')
